from typing import Dict, Any

class Document:
    def __init__(self, id: str, content: Dict[str, Any]):
        self.id = id
        self.content = content

    def to_item(self) -> Dict[str, Any]:
        item = {"id": self.id}
        item.update(self.content)
        return item

    @staticmethod
    def from_item(item: Dict[str, Any]) -> "Document":
        doc_id = item.pop("id")
        return Document(id=doc_id, content=item)

import boto3
import os

def get_dynamodb_client():
    aws_region = os.environ.get("AWS_REGION", "us-east-1")
    return boto3.client("dynamodb", region_name=aws_region)

from database_client import get_dynamodb_client
from database_models import Document

def fetch_document(table_name: str, document_id: str) -> Document | None:
    dynamodb = get_dynamodb_client()
    response = dynamodb.get_item(
        TableName=table_name,
        Key={
            'id': {'S': document_id}
        }
    )
    item = response.get('Item')
    if item:
        # Convert DynamoDB item format to a regular dictionary
        deserialized_item = {k: list(v.values())[0] for k, v in item.items()}
        return Document.from_item(deserialized_item)
    return None

